status = #{status}, pay_status = #{payStatus}, rejection_reason = #{rejectionReason}, cancel_reason = #{cancelReason}, cancel_time = #{cancelTime}, checkout_time = #{checkoutTime}, delivery_time = #{deliveryTime},
where id = #{id}

